entries[64157] = { ["name"] = "Fluch der Verdammnis", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nVerdammt das Ziel, wodurch es nach Ablauf von 12 Sek. 20000 Schattenschaden erleidet." }
entries[64158] = { ["name"] = "Unvergängliche Wache" }
entries[64159] = { ["name"] = "Blutsauger", ["text"] = "45 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 2000 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[64160] = { ["name"] = "Blutsauger", ["text"] = "45 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 3333 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
