entries[64162] = { ["name"] = "Geschwächt", ["text"] = "Sofort\nUnvergängliche Wachen sind anfällig gegen 'Titanischer Sturm', wenn ihre Gesundheit niedrig ist." }
entries[64163] = { ["name"] = "Wahnsinniger Blick", ["text"] = "Kanalisiert (Wirken in 4 sek.)\nIn den Schlund des Wahnsinns zu blicken bringt Euren Geist aus dem Gleichgewicht. Solange Ihr den Zaubernden anseht, erleidet Ihr alle 1 Sek. 5700 bis 6300 Schattenschaden und Eure geistige Gesundheit wird um 4% verringert." }
entries[64164] = { ["name"] = "Wahnsinniger Blick", ["text"] = "Unbegrenzte Reichweite\nSofort\nIn den Schlund des Wahnsinns zu blicken bringt Euren Geist aus dem Gleichgewicht. Solange Ihr den Zaubernden anseht, erleidet Ihr alle 1 Sek. 5700 bis 6300 Schattenschaden und Eure geistige Gesundheit wird um 4% verringert." }
entries[64165] = { ["name"] = "Todesanimation" }
entries[64166] = { ["name"] = "Alles Leben auslöschen", ["text"] = "Sofort\nLöscht alles Leben aus. Ende Gelände." }
entries[64167] = { ["name"] = "Wahnsinniger Blick", ["text"] = "Kanalisiert (Wirken in 1 min)\nIn den lachenden Schädel zu blicken bringt Euren Geist aus dem Gleichgewicht, verursacht 1750 Schattenschaden und verringert Eure geistige Gesundheit alle 1 Sek. um 2%, solange Ihr den Zaubernden anblickt." }
entries[64168] = { ["name"] = "Wahnsinniger Blick", ["text"] = "Unbegrenzte Reichweite\nSofort\nIn den lachenden Schädel zu blicken bringt Euren Geist aus dem Gleichgewicht, verursacht 1750 Schattenschaden und verringert Eure geistige Gesundheit alle 1 Sek. um 2%, solange Ihr den Zaubernden anblickt." }
entries[64169] = { ["name"] = "Brunnen der geistigen Gesundheit", ["text"] = "Sofort\nIm Brunnen zu stehen bringt Euch wieder zur Besinnung, Ihr regeneriert alle 2 Sek. 20% geistige Gesundheit. Während Ihr im Brunnen steht, wird Euer erlittener Schaden um 50% verringert." }
entries[64170] = { ["name"] = "Brunnen der geistigen Gesundheit", ["text"] = "Wirken in 5 sek.\nZaubert einen Brunnen der geistigen Gesundheit herbei, der die geistige Gesundheit von jedem, der sich in ihm befindet, regeneriert." }
entries[64171] = { ["name"] = "Titanischer Sturm", ["text"] = "Wirken in 5 sek.\nKanalisiert einen mächtigen Sturm titanischer Energien, der regelmäßig Feindliche Ziele mit Blitzschlägen trifft, die stark genug sind, um geschwächte unsterbliche Kreaturen zu zerstören." }
entries[64172] = { ["name"] = "Titanischer Sturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nKanalisiert einen Sturm titanischer Energien, der regelmäßig Feindliche Ziele mit Blitzschlägen trifft, die stark genug sind, um geschwächte unsterbliche Kreaturen zu zerstören." }
entries[64173] = { ["name"] = "Zerschmetterte Illusion", ["text"] = "Unbegrenzte Reichweite\nSofort\nYogg-Saron ist durch das Zerbrechen der Illusion für einen Moment betäubt." }
entries[64174] = { ["name"] = "Hodirs schützender Blick", ["text"] = "300 Meter Reichweite\nWirken in 1.5 sek.\nErmöglicht Hodir, ein befreundetes Ziel, das tödlichen Schaden erlitten hat, zu retten, indem er es bis zu bis Abbruch lang in einem fast undurchdringlichen Eisblock einschließt. Hodir muss sich nach dieser Aktion ausruhen." }
entries[64175] = { ["name"] = "Blitzeis", ["text"] = "Sofort\nIhr werdet in einen Eisblock eingehüllt, der Euch 10 Sek. lang vor allen körperlichen Angriffen und Zaubern schützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken." }
entries[64176] = { ["name"] = "Blitzeis" }
entries[64183] = { ["name"] = "Despawn Drakes" }
entries[64184] = { ["name"] = "Zwischen den Fängen des Alten Gottes", ["text"] = "20 Meter Reichweite\nSofort\nWirft die Fragmente von Val'anyr in Yogg-Sarons Schlund, während er 'Ohrenbetäubendes Gebrüll' ausführt." }
entries[64185] = { ["name"] = "Geschenk der Lebensbinderin", ["text"] = "Unbegrenzte Reichweite\nSofort\nEonars Geschenk heilt Freya und alle ihre Diener um 60% ihrer Gesundheit." }
entries[64186] = { ["name"] = "Frostflammenangriff", ["text"] = "100 Meter Reichweite\nSofort\nErfüllt die Waffe des Schamanen mit Frostmagie. Bei jedem Treffer besteht eine Chance, zusätzlichen Frostschaden zu verursachen und das Bewegungstempo des Ziels 8 Sek. lang um 50% zu verringern. Hält 30 Minuten lang an." }
entries[64187] = { ["name"] = "Sturmschild", ["text"] = "Sofort\nSchildet den Zaubernden durch Elektrizität ab, die Angreifern bei einem Treffer 250 Naturschaden zufügt. Zusätzlich wird der Zaubernde immun gegenüber Betäubungseffekten." }
entries[64188] = { ["name"] = "Halbe Heilung" }
entries[64189] = { ["name"] = "Ohrenbetäubendes Gebrüll", ["text"] = "Wirken in 2.3 sek.\nFügt 7600 bis 8400 körperlichen Schaden zu und bringt den Feind 4 Sek. lang zum Schweigen." }
entries[64190] = { ["name"] = "Gehärtete Rinde", ["text"] = "Sofort\nAngriffe gegen den Peitscher lösen den Wusch der schützenden Rinde aus, wodurch der Schaden erhöht wird. Stapelbar." }
entries[64191] = { ["name"] = "Gehärtete Rinde", ["text"] = "Sofort\nAngriffe gegen den Peitscher lösen den Wusch der schützenden Rinde aus, wodurch der verursachte Schaden erhöht wird.\n(250ms Abklingzeit)" }
