entries[64193] = { ["name"] = "Gebrochenes Herz", ["text"] = "Sofort\nDas Herz des XT-002 Dekonstruktor wurde abgeschnitten, wodurch die Kampfeinschränkungen des XT-002 Dekonstruktors entfernt wurden. Schaden um 15% erhöht. Gesundheit um 60% erhöht." }
entries[64194] = { ["name"] = "Destroy the Workbench 1" }
entries[64195] = { ["name"] = "Einfacher Teleport", ["text"] = "Sofort\nDies erzeugt einen Effekt bei dem zaubernden NSC, der ihn aussehen lässt, als wäre er gerade erst eingetroffen." }
