entries[64213] = { ["name"] = "Kettenblitzschlag", ["text"] = "150 Mana 100 Meter Reichweite\nWirken in 1 sek.\nTrifft einen Feind mit einem Blitzschlag, der 4625 bis 5375 Naturschaden verursacht. Der Blitz wird auf in der Nähe befindliche Feinde überspringen und mit jedem weiteren Ziel 50% mehr Schaden verursachen." }
entries[64215] = { ["name"] = "Kettenblitzschlag", ["text"] = "150 Mana 100 Meter Reichweite\nWirken in 1 sek.\nTrifft einen Feind mit einem Blitzschlag, der 7400 bis 8600 Naturschaden verursacht. Der Blitz wird auf in der Nähe befindliche Feinde überspringen und mit jedem weiteren Ziel 20% mehr Schaden verursachen." }
entries[64216] = { ["name"] = "Blitznova", ["text"] = "Wirken in 5 sek. 5 sek. Abklingzeit\nEmittiert einen Energiepuls, der Feinden innerhalb von 20 Metern 20813 bis 24187 Naturschaden zufügt." }
entries[64217] = { ["name"] = "Überladen", ["text"] = "Sofort\nMit unkontrollierter Kraft überladen. Erhöht den verursachten Schaden pro Stapel um 20%." }
entries[64218] = { ["name"] = "Überladen", ["text"] = "Sofort\nÜberlädt einen nahen Sturmdiener mit einem heftigen Sog Sturmenergien." }
entries[64219] = { ["name"] = "Überladener Schlag", ["text"] = "Sofort\nLässt den Zaubernden explodieren und entfesselt einen Energiepuls, der Feinden innerhalb von 50000 Metern 9250 bis 10750 Naturschaden zufügt." }
entries[64224] = { ["name"] = "Steinerner Griff", ["text"] = "Unbegrenzte Reichweite\nSofort\nAbsorbiert 80000 Schaden." }
