entries[64246] = { ["name"] = "Glyphe 'Spiegelnde Klingen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen Zaubertreffer erleidet, während 'Abschreckung' aktiv ist, besteht eine Chance von 100%, dass der Zauber auf den Zaubernden reflektiert wird." }
entries[64247] = { ["name"] = "Glyphe 'Totemische Lebenskraft'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Gesundheit Eurer Totems um 5% Eurer maximalen Gesundheit." }
entries[64248] = { ["name"] = "Glyphe 'Aderlass'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Aderlass' zehrt keine Gesundheit mehr auf, absorbiert stattdessen jedoch pro Anwendung [(Gesamtgesundheit * 0.15)] erhaltene Heilung. Dieser Effekt ist stapelbar.\n\nDie Absorption hält 30 Sek. lang an." }
entries[64249] = { ["name"] = "Glyphe 'Streuschuss'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite der Fähigkeit 'Streuschuss' um 3 Meter." }
entries[64250] = { ["name"] = "Glyphe 'Blutige Verbannung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Effekt Eures Zaubers 'Verbannung' ist nun rot." }
entries[64251] = { ["name"] = "Glyphe 'Inquisition'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Effektdauer von 'Inquisition' um 30 Sek., wenn Ihr einem Gegner den Todesstoß versetzt, der Erfahrung oder Ehre gewährt." }
entries[64252] = { ["name"] = "Glyphe 'Schildwall'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Schildwall' verringert nun den erlittenen Schaden um zusätzlich 20%, ihre Abklingzeit wird jedoch um 2 Min. erhöht." }
entries[64253] = { ["name"] = "Glyphe 'Ruf des Meisters'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Dauer Eurer Fähigkeit 'Ruf des Meisters' um 4 Sek." }
entries[64254] = { ["name"] = "Glyphe 'Heiliger Schock'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die gewirkte Heilung Eures Zaubers 'Heiliger Schock' um 50%, erhöht jedoch seinen verursachten Schaden um 50%." }
entries[64255] = { ["name"] = "Glyphe 'Siegeswurf'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Fähigkeiten 'Siegesrausch' und 'Bevorstehender Sieg' um 15 Meter." }
entries[64256] = { ["name"] = "Glyphe 'Baumrinde'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend der Zauber 'Baumrinde' aktiv ist, wird Eure Chance, kritische Treffer zu erleiden, um 25% verringert." }
entries[64257] = { ["name"] = "Glyphe 'Tieffrieren'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Tieffrieren' ist nicht mehr von globaler Abklingzeit betroffen, allerdings wird seine Dauer um 1 Sek. verringert." }
entries[64258] = { ["name"] = "Glyphe 'Wirbelsturm'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eures Zaubers 'Wirbelsturm' um 5 Meter." }
entries[64259] = { ["name"] = "Glyphe 'Verbindende Heilung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verbindende Heilung' heilt nun ein drittes Ziel innerhalb von 20 Metern, die Manakosten werden jedoch um 35% erhöht." }
entries[64260] = { ["name"] = "Glyphe 'Verkleiden'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nGeringe Glyphe\nKlassen: Schurke\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen humanoiden Gegner bestehlt, kopiert Ihr 5 Min. lang sein Erscheinungsbild. Eure Verkleidung schwindet, sobald Ihr den Kampf beginnt." }
entries[64261] = { ["name"] = "Glyphe 'Regenguss'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nGeringe Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Kettenheilung' hat nun das Erscheinungsbild von Wasser." }
entries[64262] = { ["name"] = "Glyphe 'Schamanistische Wut'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Eure Fähigkeit 'Schamanistische Wut' aktiviert, werden gleichzeitig alle bannbaren magischen Schwächungseffekte entfernt." }
entries[64264] = { ["name"] = "Force Master Ride Brutusk 03" }
