entries[64266] = { ["name"] = "Glyphe 'Todesmantel'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Todesritter\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Todesmantel' kann nun auf alle Verbündeten gewirkt werden. Wenn der Zauber einen nicht-untoten Verbündeten trifft, hüllt 'Todesmantel' ihn in eine schützende Barriere, die bis zu [( 75 + 0.514 * Angriffskraft) * 1 ] Schaden absorbiert." }
entries[64268] = { ["name"] = "Glyphe 'Überlebensinstinkte'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Überlebensinstinkte' um 60 Sek., verringert aber die Dauer um 50%." }
entries[64269] = { ["name"] = "Kanalisierung von Freyas Hologramm" }
entries[64270] = { ["name"] = "Glyphe 'Wildwuchs'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBis zu 1 zusätzliches Ziel kann nun von Eurem Zauber 'Wildwuchs' betroffen sein, die Abklingzeit des Zaubers wird jedoch um 2 Sek. erhöht." }
entries[64271] = { ["name"] = "Glyphe 'Schimärenschuss'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht Eure durch 'Schimärenschuss' erhaltene Heilung um zusätzlich 2% Eurer maximalen Gesundheit." }
entries[64272] = { ["name"] = "Kadrak reitet" }
entries[64273] = { ["name"] = "Glyphe 'Einlullender Schuss'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Einlullender Schuss' kostet keinen Fokus mehr, hat jedoch eine Abklingzeit von 10 Sek." }
entries[64274] = { ["name"] = "Glyphe 'Wasserelementar'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Gesundheit Eures Wasserelementars um 40% und ermöglicht es ihm, Zauber während der Bewegung zu wirken. Im Hilfsmodus im Kampf bewirkt der Befehl 'Folgen', dass er in Eurer Nähe bleibt und automatisch 'Wasserblitz' wirkt, wenn ein Ziel in Reichweite gelangt." }
entries[64275] = { ["name"] = "Glyphe 'Verlangsamen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Arkanschlag' belegt ein beliebiges Ziel, dem er Schaden zufügt, mit dem Effekt Eures Zaubers 'Verlangsamen', soweit zu diesem Zeitpunkt kein anderes Ziel mit Eurem Zauber 'Verlangsamen' belegt ist." }
entries[64276] = { ["name"] = "Glyphe 'Illusion'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nGeringe Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch die Fähigkeit 'Illusion'.\n\nLässt Euch 2 Min. lang das Aussehen von jemand anderem annehmen." }
entries[64277] = { ["name"] = "Glyphe 'Flamme des Glaubens'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEntfernt die globale Abklingzeit von 'Flamme des Glaubens'." }
