entries[64281] = { ["name"] = "Glyphe 'Glaubenssprung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Glaubenssprung' entfernt nun alle bestehenden bewegungeinschränkenden Effekte vom Ziel." }
entries[64282] = { ["name"] = "Glyphe 'Sühne'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Manakosten von 'Sühne' um 20%, Ihr könnt den Zauber jedoch während des Laufens wirken." }
entries[64283] = { ["name"] = "Glyphe 'Gedankenstachel'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErfolgreiches Wirken von 'Gedankenstachel' mit Zauberzeit verringert die Zauberzeit Eures nächsten Wirkens von 'Gedankenschlag' innerhalb von 9 Sek. um 50%. Dieser Effekt ist bis zu 2-mal stapelbar." }
