entries[64285] = { ["name"] = "Glyphe 'Mordlust'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nGeringe Glyphe\nKlassen: Schurke\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn der Effekt Eurer Fähigkeit 'Mordlust' endet, werdet Ihr an Euren Anfangspunkt zurückversetzt." }
