entries[64298] = { ["name"] = "Glyphe 'Dunkles Simulakrum'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Todesritter\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Dunkles Simulakrum' um 30 Sek. und erhöht die Effektdauer um 4 Sek." }
entries[64300] = { ["name"] = "Glyphe 'Ruhiger Griff'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nGeringe Glyphe\nKlassen: Todesritter\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Todesgriff' verspottet das Ziel nicht mehr." }
entries[64302] = { ["name"] = "Glyphe 'Zauberreflexion'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Zauberreflexion' um 5 Sek." }
entries[64303] = { ["name"] = "Glyphe 'Mantel der Schatten'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Schurke\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend die Fähigkeit 'Mantel der Schatten' aktiv ist, erleidet Ihr 40% weniger körperlichen Schaden." }
entries[64304] = { ["name"] = "Glyphe 'Aspekt des Geparden'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIst Eure Fähigkeit 'Aspekt des Geparden' aktiv, werdet Ihr nicht mehr benommen, wenn Ihr getroffen werdet. Stattdessen wird der Effekt abgebrochen und alle Eure Aspekte werden mit einer Abklingzeit von 4 Sek. belegt." }
entries[64305] = { ["name"] = "Glyphe 'Göttliche Bitte'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Göttliche Bitte' stellt 50% weniger Mana wieder her, dafür ist die Abklingzeit 50% kürzer." }
entries[64306] = { ["name"] = "Siechenden Ent rufen", ["text"] = "10 Meter Reichweite\nSofort 3 sek. Abklingzeit\nLässt aus den nährstoffreichen Überresten eines Spähers der Dunkelschuppen einen Ent erwachsen." }
