entries[64308] = { ["name"] = "Glyphe 'Alabasterschild'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErfolgreiches Blocken erhöht den Schaden Eures nächsten Einsatzes von 'Schild der Rechtschaffenen' um 10%. Bis zu 3-mal stapelbar." }
entries[64309] = { ["name"] = "Glyphe 'Gebündelte Besserung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Gebet der Besserung' springt nur noch zwischem dem Ziel und dem Zaubernden hin und her." }
entries[64310] = { ["name"] = "Glyphe 'Schurkenhandel'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Schurke\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Energiekosten Eurer Fähigkeit 'Schurkenhandel' um 100%, dem Ziel wird jedoch kein Schadensbonus mehr gewährt." }
entries[64311] = { ["name"] = "Glyphe 'Erbarmungslose Entschlossenheit'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDie Schadensverringerung Eures Zaubers 'Erbarmungslose Entschlossenheit' wird um 20% verringert, die Abklingzeit wird um 60 Sek. verringert." }
entries[64312] = { ["name"] = "Glyphe 'Drohruf'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDie Ziele Eurer Fähigkeit 'Drohruf' fliehen nun nicht mehr, sondern erzittern vor Furcht." }
entries[64313] = { ["name"] = "Glyphe 'Ursocs Macht'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die von Eurer Fähigkeit 'Ursocs Macht' gewährte Gesundheit um 20%, erhöht jedoch die Abklingzeit um 2 Min." }
